class Command(BaseCommand):
    help = "Create or update the default Persian support FAQ entries."

    def handle(self, *args, **options):
        created_count = 0
        updated_count = 0

        for order, item in enumerate(FAQS, start=1):
            _, created = FAQ.objects.update_or_create(
                category=item["category"],
                question=item["question"],
                defaults={
                    "answer": item["answer"],
                    "tags": item["tags"],
                    "is_active": True,
                    "sort_order": order * 10,
                },
            )
            if created:
                created_count += 1
            else:
                updated_count += 1

        self.stdout.write(
            self.style.SUCCESS(
                f"FAQ seeding complete: {created_count} created, "
                f"{updated_count} updated, {FAQ.objects.filter(is_active=True).count()} active FAQs."
            )
        )
